10	        GMMA::Layout_K_INTER_Atom<cute::bfloat16_t>{},
11	        make_shape(Int<CHUNK>{}, Int<D>{}),
12	        LayoutLeft{}
13	    ));
14	    using BetaSmemLayout = Layout<Shape<Int<32>>, Stride<Int<1>>>;
15	    using GTotalLayout = Layout<Shape<Int<D>>, Stride<Int<1>>>;
16	    using LMLayout = decltype(tile_to_shape(
17	        GMMA::Layout_K_INTER_Atom<cute::bfloat16_t>{},
18	        make_shape(Int<CHUNK>{}, Int<CHUNK>{}),
19	        LayoutLeft{}
20	    ));
21	    using LF32Layout = decltype(make_layout(make_shape(Int<CHUNK>{}, Int<CHUNK>{}), LayoutRight{}));
22	    using TransposedLMLayout = decltype(tile_to_shape(
23	        GMMA::Layout_MN_INTER_Atom<cute::bfloat16_t>{},
24	        make_shape(Int<CHUNK>{}, Int<CHUNK>{}),
25	        LayoutRight{}
26	    ));
27	
28	    using TMABetaSmemLayout = BetaSmemLayout;  // 1D TMA, no dummy dim
29	    using TMAQKLayout = decltype(prepend(QKLayout{}));
30	    using TMAVOLayout = decltype(composition(
31	        MMALayout{}.layout_a(),
32	        MMALayout{}.offset(),
33	        prepend(MMALayout{}.layout_b())
34	    ));
35	    using TMAGLayout = decltype(prepend(GLayout{}));
36	    using TMALMLayout = decltype(composition(
37	        LMLayout{}.layout_a(),
38	        LMLayout{}.offset(),
39	        prepend(LMLayout{}.layout_b())
40	    ));
