86	// Build prefix-sum of per-sequence tile counts, so Kernel 1 can map
87	// global_tile_idx -> seq_idx with an O(log N) binary search instead of an
88	// O(N) linear scan per CTA in varlen mode.
89	__global__ void _flash_kda_build_tile_prefix(
90	    int64_t const* __restrict__ cu_seqlens,
91	    int N,
92	    int chunk,
93	    int* __restrict__ tile_prefix
94	) {
95	    if (threadIdx.x == 0) {
96	        int acc = 0;
97	        tile_prefix[0] = 0;
98	        for (int i = 0; i < N; ++i) {
99	            int slen = int(cu_seqlens[i + 1] - cu_seqlens[i]);
100	            acc += (slen + chunk - 1) / chunk;
101	            tile_prefix[i + 1] = acc;
102	        }
103	    }
104	}
