511	    inv_fwd_subst_fused_1warp(L_fp32, M_bf16, INV, compute_tid);
512	    // Fence + sync combined: completion + TMA visibility
513	    cutlass::arch::fence_view_async_shared();
514	    __syncthreads();
515	    if (threadIdx.x == 0) {
516	        int ws_idx = head_idx * total_tiles + global_tile_idx;
517	        // Store k_decayed [CHUNK, D] bf16
518	        {
519	            auto g_ws = tma_store_ws_kd.get_tma_tensor(make_shape(H * total_tiles, CHUNK, D));
520	            auto ws_off = g_ws.layout()(ws_idx, 0, 0);
521	            Tensor g_ws_tile = make_tensor(g_ws.data() + ws_off,
522	                make_layout(make_shape(Int<1>{}, Int<CHUNK>{}, Int<D>{}), stride(g_ws.layout())));
523	            Tensor s_kd = make_tensor(make_smem_ptr(shared_storage.k_decayed.begin()), TMAVOLayout{});
524	            auto cta_tma = tma_store_ws_kd.get_slice(Int<0>{});
525	            cute::copy(tma_store_ws_kd, cta_tma.partition_S(s_kd), cta_tma.partition_D(g_ws_tile));
526	            tma_store_arrive();
527	        }
528	        // Store q_decayed
529	        {
530	            auto g_ws = tma_store_ws_qd.get_tma_tensor(make_shape(H * total_tiles, CHUNK, D));
531	            auto ws_off = g_ws.layout()(ws_idx, 0, 0);
532	            Tensor g_ws_tile = make_tensor(g_ws.data() + ws_off,
533	                make_layout(make_shape(Int<1>{}, Int<CHUNK>{}, Int<D>{}), stride(g_ws.layout())));
534	            Tensor s_qd = make_tensor(make_smem_ptr(shared_storage.q_decayed.begin()), TMAVOLayout{});
535	            auto cta_tma = tma_store_ws_qd.get_slice(Int<0>{});
536	            cute::copy(tma_store_ws_qd, cta_tma.partition_S(s_qd), cta_tma.partition_D(g_ws_tile));
537	            tma_store_arrive();
538	        }
539	        // Store k_restored
540	        {
541	            auto g_ws = tma_store_ws_kr.get_tma_tensor(make_shape(H * total_tiles, CHUNK, D));
542	            auto ws_off = g_ws.layout()(ws_idx, 0, 0);
543	            Tensor g_ws_tile = make_tensor(g_ws.data() + ws_off,
544	                make_layout(make_shape(Int<1>{}, Int<CHUNK>{}, Int<D>{}), stride(g_ws.layout())));
545	            Tensor s_kr = make_tensor(make_smem_ptr(shared_storage.k_restored.begin()), TMAVOLayout{});
546	            auto cta_tma = tma_store_ws_kr.get_slice(Int<0>{});
547	            cute::copy(tma_store_ws_kr, cta_tma.partition_S(s_kr), cta_tma.partition_D(g_ws_tile));
548	            tma_store_arrive();
549	        }
